##


@dc.dataclass(eq=False)
class ArgparseArg:
    args: ta.Sequence[ta.Any]
    kwargs: ta.Mapping[str, ta.Any]
    group: ta.Optional[str] = None
    dest: ta.Optional[str] = None

    def __get__(self, instance, owner=None):
        if instance is None:
            return self
        return getattr(instance.args, self.dest)  # type: ignore


def argparse_arg(*args, **kwargs) -> ArgparseArg:
    return ArgparseArg(
        args=args,
        group=kwargs.pop('group', None),
        kwargs=kwargs,
    )


def argparse_arg_(*args, **kwargs) -> ta.Any:
    return argparse_arg(*args, **kwargs)


#


@dc.dataclass(eq=False)
class ArgparseCmd:
    name: str
    fn: ArgparseCmdFn
    args: ta.Sequence[ArgparseArg] = ()  # noqa

    # _: dc.KW_ONLY

    aliases: ta.Optional[ta.Sequence[str]] = None
    parent: ta.Optional['ArgparseCmd'] = None
    accepts_unknown: bool = False
    default: bool = False

    no_help: bool = False

    def __post_init__(self) -> None:
        def check_name(s: str) -> None:
            check.isinstance(s, str)
            check.not_in('_', s)
            check.not_empty(s)

        check_name(self.name)
        check.arg(callable(self.fn))
        check.arg(all(isinstance(a, ArgparseArg) for a in self.args))

        check.not_isinstance(self.aliases, str)
        for a in self.aliases or []:
            check_name(a)
        check.isinstance(self.parent, (ArgparseCmd, type(None)))
        check.isinstance(self.accepts_unknown, bool)

        functools.update_wrapper(self, self.fn)

    def __get__(self, instance, owner=None):
        if instance is None:
            return self
        return dc.replace(self, fn=self.fn.__get__(instance, owner))  # noqa

    def __call__(self, *args, **kwargs) -> ta.Union[ta.Optional[int], ta.Awaitable[ta.Optional[int]]]:
        return self.fn(*args, **kwargs)


def argparse_cmd(
        *args: ArgparseArg,
        name: ta.Optional[str] = None,

        aliases: ta.Optional[ta.Iterable[str]] = None,
        parent: ta.Optional[ArgparseCmd] = None,
        accepts_unknown: bool = False,
        default: bool = False,

        no_help: bool = False,
) -> ta.Any:  # ta.Callable[[ArgparseCmdFn], ArgparseCmd]:  # FIXME
    for arg in args:
        check.isinstance(arg, ArgparseArg)
    check.isinstance(name, (str, type(None)))

    check.isinstance(parent, (ArgparseCmd, type(None)))
    check.not_isinstance(aliases, str)
    check.isinstance(default, bool)

    def inner(fn):
        return ArgparseCmd(
            (name if name is not None else fn.__name__).replace('_', '-'),
            fn,
            args,

            aliases=tuple(aliases) if aliases is not None else None,
            parent=parent,
            accepts_unknown=accepts_unknown,
            default=default,

            no_help=no_help,
        )

    return inner


##


def _get_argparse_arg_ann_kwargs(ann: ta.Any) -> ta.Mapping[str, ta.Any]:
    if ann is str:
        return {}
    elif ann is int:
        return {'type': int}
    elif ann is bool:
        return {'action': 'store_true'}
    elif ann is list:
        return {'action': 'append'}
    elif is_optional_alias(ann):
        return _get_argparse_arg_ann_kwargs(get_optional_alias_arg(ann))
    else:
        raise TypeError(ann)


class _ArgparseParserClassAnnotationBox:
    def __init__(self, annotations: ta.Mapping[str, ta.Any]) -> None:
        super().__init__()

        self.__annotations__ = annotations  # type: ignore


def configure_argparse_parser_class_parser(
        cls: type,
        parser: ta.Optional[argparse.ArgumentParser] = None,
) -> argparse.ArgumentParser:
    ns = cls.__dict__
    objs = {}
    for bcls in reversed(cls.__mro__):
        bns = bcls.__dict__
        bseen = set()  # type: ignore
        for k, v in bns.items():
            if isinstance(v, (ArgparseCmd, ArgparseArg)):
                check.not_in(v, bseen)
                bseen.add(v)
                objs[k] = v
            elif k in objs:
                del objs[k]

    #

    anns = ta.get_type_hints(_ArgparseParserClassAnnotationBox({
        k: v
        for bcls in reversed(cls.__mro__)
        for k, v in getattr(bcls, '__annotations__', {}).items()
    }), globalns=ns.get('__globals__', {}))

    #

    if parser is None:
        parser = argparse.ArgumentParser()

    #

    subparsers = parser.add_subparsers()

    default_cmd: ta.Optional[ArgparseCmd] = None

    for att, obj in objs.items():
        if isinstance(obj, ArgparseCmd):
            if obj.parent is not None:
                raise NotImplementedError

            if obj.default:
                if default_cmd:
                    raise TypeError(f'Already have a default command: {default_cmd}, {obj}')
                default_cmd = obj

            for cn in [obj.name, *(obj.aliases or [])]:
                subparser = subparsers.add_parser(
                    cn,
                    **(dict(add_help=False) if obj.no_help else {}),  # type: ignore[arg-type]
                )

                for arg in (obj.args or []):
                    if (
                            len(arg.args) == 1 and
                            isinstance(arg.args[0], str) and
                            not (n := check.isinstance(arg.args[0], str)).startswith('-') and
                            'metavar' not in arg.kwargs
                    ):
                        subparser.add_argument(
                            n.replace('-', '_'),
                            **arg.kwargs,
                            metavar=n,
                        )
                    else:
                        subparser.add_argument(*arg.args, **arg.kwargs)

                subparser.set_defaults(_cmd=obj)

        elif isinstance(obj, ArgparseArg):
            if obj.group is not None:
                # FIXME: add_argument_group
                raise NotImplementedError

            if att in anns:
                ann_kwargs = _get_argparse_arg_ann_kwargs(anns[att])
                obj.kwargs = {**ann_kwargs, **obj.kwargs}

            if not obj.dest:
                if 'dest' in obj.kwargs:
                    obj.dest = obj.kwargs['dest']
                else:
                    obj.dest = obj.kwargs['dest'] = att  # type: ignore

            parser.add_argument(*obj.args, **obj.kwargs)

        else:
            raise TypeError(obj)

    if default_cmd is not None:
        parser.set_defaults(_cmd=default_cmd)

    return parser


##


class ArgparseParserClass(Abstract):
    def __init_subclass__(cls, **kwargs: ta.Any) -> None:
        super().__init_subclass__(**kwargs)

        ns = cls.__dict__

        if '_parser' in ns:
            parser = check.isinstance(ns['_parser'], argparse.ArgumentParser)
        else:
            parser = argparse.ArgumentParser()

        configure_argparse_parser_class_parser(cls, parser)

        setattr(cls, '_parser', parser)

    #

    _parser: ta.ClassVar[argparse.ArgumentParser]

    @classmethod
    def get_parser(cls) -> argparse.ArgumentParser:
        return cls._parser


