def asyncio_maybe_timeout(
        fut: AwaitableT,
        timeout: TimeoutLike = None,
) -> AwaitableT:
    if timeout is not None:
        try:
            seconds = Timeout.of(timeout)()
        except BaseException:
            asyncio.ensure_future(fut).cancel()
            raise
        fut = asyncio.wait_for(fut, seconds)  # type: ignore
    return fut


